  version_tag = EXCLUDED.version_tag,
  effective_from = EXCLUDED.effective_from,
  default_status = EXCLUDED.default_status,
  record_count = EXCLUDED.record_count,
  metadata = EXCLUDED.metadata;

-- ─── 2. MIGRATION CONFLICT TRACKING INFRASTRUCTURE ───────────────────────────

CREATE TABLE IF NOT EXISTS public.migration_conflicts (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  source TEXT NOT NULL,
  source_record_id TEXT NOT NULL,
  candidate_canonical_id UUID,
  entity_type TEXT NOT NULL,
  conflict_reason TEXT NOT NULL,
  conflict_payload JSONB NOT NULL DEFAULT '{}'::jsonb,
  confidence DOUBLE PRECISION NOT NULL DEFAULT 1.0,
  status TEXT NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN', 'RESOLVED', 'DISMISSED')),
  resolution TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_migration_conflicts_status ON public.migration_conflicts(status);
CREATE INDEX IF NOT EXISTS idx_migration_conflicts_entity ON public.migration_conflicts(entity_type, source);

