-- ─── 8. CANONICAL CONSTITUENCY VERSIONS (4,123 VERSIONS) ───────────────────────

INSERT INTO public.constituency_versions (
  constituency_internal_id, delimitation_regime_id, version_code, canonical_code, ac_no, name, reservation, valid_from, valid_to, is_current, primary_dataset_version_id
)
SELECT
  c.internal_id,
  c.delimitation_regime_id,
  c.canonical_code || '-2008',
  c.canonical_code,
  c.ac_no,
  c.name,
  CASE LOWER(COALESCE(c.reservation_status, 'general'))
    WHEN 'gen' THEN 'general'
    WHEN 'sc' THEN 'sc'
    WHEN 'st' THEN 'st'
    ELSE 'general'
  END,
  c.valid_from,
  NULL,
  true,
  c.primary_dataset_version_id
FROM public.constituencies c
ON CONFLICT (version_code) DO UPDATE SET
  name = EXCLUDED.name,
  reservation = EXCLUDED.reservation,
  valid_from = EXCLUDED.valid_from,
  is_current = EXCLUDED.is_current,
  updated_at = now();

UPDATE public.constituencies c
SET current_version_id = cv.id
FROM public.constituency_versions cv
WHERE c.internal_id = cv.constituency_internal_id AND cv.is_current = true;

-- ─── 9. STATUTORY PROVENANCE LINKAGES ─────────────────────────────────────────

INSERT INTO public.record_provenance_linkages (domain_table, domain_record_id, provenance_id, is_canonical)
SELECT 'states', s.code, '00000000-0000-0000-0013-000000000001'::uuid, true
FROM public.states s
ON CONFLICT (domain_table, domain_record_id, provenance_id) DO NOTHING;

INSERT INTO public.record_provenance_linkages (domain_table, domain_record_id, provenance_id, is_canonical)
